TaskDBResult<bool> TaskDatabaseManager::add_history_entry(const TaskHistoryRecord& entry) {
    auto conn_result = pg_pool_->acquire();
    if (!conn_result) {
        return TaskDBError{TaskDBErrorCode::POOL_EXHAUSTED, "..."};
    }

    auto conn = *conn_result;
    const char* sql = 
        "INSERT INTO task_history (history_id, task_id, operation, field_name, "
        "old_value, new_value, performed_by, task_version) "
        "VALUES ($1, $2, $3, $4, $5, $6, $7, $8)";

    const char* params[8] = {
        entry.history_id.c_str(),
        entry.task_id.c_str(),
        entry.operation.c_str(),
        entry.field_name.c_str(),
        entry.old_value ? entry.old_value->c_str() : nullptr,
        entry.new_value ? entry.new_value->c_str() : nullptr,
        entry.performed_by.c_str(),
        std::to_string(entry.task_version).c_str()
    };

    PGresult* res = PQexecParams(conn->conn, sql, 8, nullptr, params, nullptr, nullptr, 0);
    // ... error handling
