namespace MedDav {
namespace QualityGate {

// UnifiedSessionId implementation
UnifiedSessionId::UnifiedSessionId(PlatformType platform,
                                   const std::string& workspace_path,
                                   const std::optional<std::string>& native_session_id,
                                   const PlatformIdentityConfig& config)
    : platform_(platform)
    , native_session_id_(native_session_id)
    , config_(config)
    , timestamp_(generate_timestamp()) {
    workspace_hash_ = hash_workspace(workspace_path);
}

std::string UnifiedSessionId::hash_workspace(const std::string& workspace_path) const {
    // Use SHA-256 with salt
    std::string salted = workspace_path + config_.workspace_hash_salt;

    EVP_MD_CTX* ctx = EVP_MD_CTX_new();
    unsigned char hash[EVP_MAX_MD_SIZE];
    unsigned int hash_len;

    EVP_DigestInit_ex(ctx, EVP_sha256(), nullptr);
    EVP_DigestUpdate(ctx, salted.c_str(), salted.length());
    EVP_DigestFinal_ex(ctx, hash, &hash_len);
    EVP_MD_CTX_free(ctx);

    // Return first 16 chars of hex-encoded hash
    std::stringstream ss;
    for (unsigned int i = 0; i < 8 && i < hash_len; ++i) {
        ss << std::hex << std::setw(2) << std::setfill('0') << (int)hash[i];
    }
    return ss.str();
}

std::string UnifiedSessionId::generate_timestamp() const {
    auto now = std::chrono::system_clock::now();
    auto ms = std::chrono::duration_cast<std::chrono::milliseconds>(now.time_since_epoch());
    return std::to_string(ms.count());
}

