PlatformType SessionIdentityResolver::detect_platform(
    const std::map<std::string, std::string>& headers,
    const std::map<std::string, std::string>& query_params) {

    // Check headers first
    if (headers.contains("X-Platform")) {
        return platform_from_string(headers.at("X-Platform"));
    }
    if (headers.contains("User-Agent")) {
        const auto& ua = headers.at("User-Agent");
        if (ua.find("Cursor") != std::string::npos) return PlatformType::CURSOR;
        if (ua.find("Claude") != std::string::npos) return PlatformType::CLAUDE_CODE;
        if (ua.find("Kimi") != std::string::npos) return PlatformType::KIMI_CODE;
    }

    // Check query params
    if (query_params.contains("platform")) {
        return platform_from_string(query_params.at("platform"));
    }

    return PlatformType::UNKNOWN;
}

