    c.description = description;
    c.target_files = target_files;
    c.metadata = metadata;
    c.status = CommitmentStatus::PENDING;
    c.created_at = std::chrono::system_clock::now();
    c.updated_at = c.created_at;
    c.expires_at = c.created_at + std::chrono::minutes(config_.session_timeout_minutes);

    // Parse platform from session_id
    if (auto parsed = UnifiedSessionId::from_string(session_id)) {
        c.originating_platform = parsed->get_platform();
    } else {
        c.originating_platform = PlatformType::UNKNOWN;
    }
    c.platform_history.push_back(c.originating_platform);

    return repo_.create(c);
}

