```bash
# Add repository
curl -fsSL https://downloads.psiforcedb.com/repo/setup.sh | sudo bash

# Install with development tools
sudo apt-get update
sudo apt-get install psiforcedb-dev psiforcedb-headers psiforcedb-tools
