### Advanced PFQL Operations
```cpp
#include <psiforcedb/pfql.h>

class UserService {
private:
    Database& db;

public:
    UserService(Database& database) : db(database) {}

    // Create user with validation
    bool createUser(const std::string& id, const std::string& name,
                   const std::string& email) {
        // Validate email format
        if (!isValidEmail(email)) {
            throw std::invalid_argument("Invalid email format");
        }

        // Insert user using PFQL
        std::string cmd = fmt::format(
            "pf://db::insert; users '{}' '{}' '{}' '{}'",
            id, name, email, getCurrentTimestamp()
        );

        auto result = db.execute(cmd);
        return result.success;
    }

    // Find users with complex filtering
    std::vector<User> findActiveUsers(int minAge = 18) {
        std::string cmd = fmt::format(
            "pf://db::select; users "
            "--where=\"age >= {} AND status='active'\" "
            "--order-by=created_at "
            "--limit=100",
            minAge
        );

        auto result = db.execute(cmd);

        if (result.success) {
            return parseUsersFromJson(result.data);
        }

        throw std::runtime_error("Failed to query users");
    }

    // Batch operations for performance
    bool bulkInsertUsers(const std::vector<User>& users) {
        // Start batch mode
        db.beginTransaction();

        try {
            for (const auto& user : users) {
                std::string cmd = fmt::format(
                    "pf://db::insert; users '{}' '{}' '{}' '{}' --batch",
                    user.id, user.name, user.email, user.created_at
                );

                auto result = db.execute(cmd);
                if (!result.success) {
                    db.rollbackTransaction();
                    return false;
                }
            }

            // Commit all inserts
            db.commitTransaction();
            return true;

        } catch (...) {
            db.rollbackTransaction();
            throw;
        }
    }
};
```

## 🔐 Security Integration

### JWT Authentication
```cpp
#include <psiforcedb/security.h>

class SecureDatabaseService {
private:
    Database db;
    JWTManager jwtManager;

public:
    bool login(const std::string& username, const std::string& password) {
        // Authenticate user
        auto authResult = jwtManager.authenticate(username, password);

        if (authResult.success) {
            // Set JWT token for database operations
            db.setAuthToken(authResult.token);

            // Store user permissions
            currentUserPermissions = authResult.permissions;

            return true;
        }

        return false;
    }

    // Role-based access control
    bool hasPermission(const std::string& permission) {
        return currentUserPermissions.has(permission);
    }

    // Secure data access
    std::string getSecureData(const std::string& table,
                             const std::string& condition) {
        if (!hasPermission("read_sensitive_data")) {
            throw std::runtime_error("Insufficient permissions");
        }

        std::string cmd = fmt::format(
            "pf://db::select; {} --where=\"{}\" --encrypt",
            table, condition
        );

        auto result = db.execute(cmd);
        return result.success ? result.data : "";
    }
};
```

