public:
    ApiIntegrationService() : client("https://api.psiforcedb.com") {
        client.setApiKey(getApiKey());
    }

    // Synchronize with remote database
    bool syncData(const std::string& localTable,
                  const std::string& remoteEndpoint) {
        std::string cmd = fmt::format(
            "pf://db::select; {} --format=json",
            localTable
        );

        auto localData = client.execute(cmd);

        // Send to remote API
        auto response = client.post(remoteEndpoint, localData.data);

        return response.success;
    }

    // Stream real-time updates
    void subscribeToChanges(const std::string& table,
                           std::function<void(const ChangeEvent&)> callback) {
        std::string cmd = fmt::format(
            "pf://stream::monitor; {} --action=callback",
            table
        );

        client.subscribe(cmd, callback);
    }
};
