```cpp
class DatabaseService {
public:
    Result<User> getUser(const std::string& userId) {
        try {
            std::string cmd = fmt::format(
                "pf://db::select; users --where=\"id='{}'\"",
                userId
            );

            auto result = db.execute(cmd);

            if (!result.success) {
                return Result<User>::error(
                    ErrorCode::DATABASE_ERROR,
                    result.error_message
                );
            }

            auto users = parseUsers(result.data);
            if (users.empty()) {
                return Result<User>::error(
                    ErrorCode::NOT_FOUND,
                    "User not found"
                );
            }

            return Result<User>::success(users[0]);

        } catch (const std::exception& e) {
            return Result<User>::error(
                ErrorCode::INTERNAL_ERROR,
                std::string("Internal error: ") + e.what()
            );
