        if (cached) {
            return *cached;
        }

        // Fetch from database
        auto user = getUser(userId);
        if (user) {
            // Store in cache with TTL
            cache.set("user_" + userId, *user, std::chrono::minutes(30));
            return *user;
        }

        throw std::runtime_error("User not found");
    }
