                config_.get("cache_size", 1000),
                config_.get("cache_ttl", 300)
            );

            logger_->info("External storage extension initialized");
            return true;
        } catch (const std::exception& e) {
            logger_->error("Failed to initialize storage extension: {}", e.what());
            return false;
        }
    }

    StorageResult read(const StorageKey& key) override {
        // Check cache first
        if (auto cached = cacheManager_->get(key); cached) {
            metrics_->increment("cache_hits");
            return StorageResult::success(*cached);
        }

        // Read from external storage
        auto connection = connectionPool_->acquire();
        auto result = client_->read(key, connection);

        if (result.success) {
            // Cache the result
            cacheManager_->put(key, result.data);
            metrics_->increment("external_reads");
        }

        return result;
    }
};
