// my_extension.cpp
#include "my_extension.h"
#include <psiforcedb/logging.h>
#include <psiforcedb/utils.h>
#include <iostream>
#include <algorithm>

// Extension metadata
std::string MyCustomExtension::getName() const {
    return "MyCustomExtension";
}

std::string MyCustomExtension::getVersion() const {
    return "1.0.0";
}

std::string MyCustomExtension::getDescription() const {
    return "A custom extension demonstrating PsiForceDB extension development";
}

std::string MyCustomExtension::getAuthor() const {
    return "Your Name <your.email@example.com>";
}

// Initialization
bool MyCustomExtension::initialize(const ExtensionContext& context) {
    if (initialized_) {
        return true;
    }

    try {
        // Get configuration
        config_path_ = context.getConfigPath() + "/my_extension.conf";

        // Initialize resources
        PsiForceDB::Logger::info("Initializing MyCustomExtension");

        // Register custom functions
        context.registerFunction("my_custom_function", [this](
            const std::vector<PsiForceDB::Value>& args) -> PsiForceDB::Value {
            return this->customFunctionImplementation(args);
        });

        // Register event handlers
        context.addEventListener("table_created", [this](const DatabaseEvent& event) {
            this->onTableCreated(event);
        });

        initialized_ = true;
        PsiForceDB::Logger::info("MyCustomExtension initialized successfully");
        return true;

    } catch (const std::exception& e) {
        PsiForceDB::Logger::error("Failed to initialize MyCustomExtension: " + std::string(e.what()));
        return false;
    }
}

// Shutdown
void MyCustomExtension::shutdown() {
    if (!initialized_) {
        return;
    }

    PsiForceDB::Logger::info("Shutting down MyCustomExtension");

    // Cleanup resources
    // ...

    initialized_ = false;
}

// Command handling
ExtensionResult MyCustomExtension::handleCommand(
    const std::string& command,
    const std::vector<std::string>& args,
    const std::map<std::string, std::string>& options) {

    try {
        if (command == "custom_function") {
            return handleCustomFunction(args, options);
        } else if (command == "data_processor") {
            return handleDataProcessor(args, options);
        } else {
            return ExtensionResult::error("Unknown command: " + command);
        }
    } catch (const std::exception& e) {
        return ExtensionResult::error("Command execution failed: " + std::string(e.what()));
    }
}

// Custom function implementation
ExtensionResult MyCustomExtension::handleCustomFunction(
    const std::vector<std::string>& args,
    const std::map<std::string, std::string>& options) {

    // Validate arguments
    if (args.empty()) {
        return ExtensionResult::error("At least one argument required");
    }

    // Process arguments
    std::string input = args[0];
    std::string operation = "uppercase"; // default

    // Check options
    auto op_it = options.find("operation");
    if (op_it != options.end()) {
        operation = op_it->second;
    }

    // Perform operation
    std::string result;
    if (operation == "uppercase") {
        result = PsiForceDB::Utils::toUpper(input);
    } else if (operation == "lowercase") {
        result = PsiForceDB::Utils::toLower(input);
    } else if (operation == "reverse") {
        result = std::string(input.rbegin(), input.rend());
    } else {
        return ExtensionResult::error("Unknown operation: " + operation);
    }

    return ExtensionResult::success(result);
}

// Data processor implementation
ExtensionResult MyCustomExtension::handleDataProcessor(
    const std::vector<std::string>& args,
    const std::map<std::string, std::string>& options) {

    // Example: Process data with custom logic
    std::vector<std::string> processed_data;

    for (const auto& arg : args) {
        // Apply custom processing
        std::string processed = "processed_" + arg;

        // Check for encryption option
        auto encrypt_it = options.find("encrypt");
        if (encrypt_it != options.end() && encrypt_it->second == "true") {
            processed = PsiForceDB::Utils::base64Encode(processed);
        }

        processed_data.push_back(processed);
    }

    // Return results as JSON
    std::string json_result = "{";
    for (size_t i = 0; i < processed_data.size(); ++i) {
        if (i > 0) json_result += ",";
        json_result += "\"" + std::to_string(i) + "\":\"" + processed_data[i] + "\"";
    }
    json_result += "}";

    return ExtensionResult::success(json_result);
}

// Event handling
void MyCustomExtension::onDatabaseEvent(const DatabaseEvent& event) {
    if (event.type == "table_created") {
        PsiForceDB::Logger::info("Table created: " + event.data.getString("table_name"));
    }
}

// Custom function implementation for database functions
PsiForceDB::Value MyCustomExtension::customFunctionImplementation(
    const std::vector<PsiForceDB::Value>& args) {

    if (args.empty()) {
        return PsiForceDB::Value::null();
    }

    // Example: Concatenate all arguments with separator
    std::string separator = "_";
    std::string result;

    for (size_t i = 0; i < args.size(); ++i) {
        if (i > 0) result += separator;
        result += args[i].toString();
    }

    return PsiForceDB::Value(result);
}

// Event handler for table creation
void MyCustomExtension::onTableCreated(const DatabaseEvent& event) {
    std::string table_name = event.data.getString("table_name");
    PsiForceDB::Logger::info("Custom extension detected table creation: " + table_name);

    // Perform custom actions when table is created
