// Performance optimization techniques:

// 1. Caching for expensive operations
class ResultCache {
private:
    std::unordered_map<std::string, CachedResult> cache_;
    std::mutex cache_mutex_;

public:
    std::optional<CachedResult> get(const std::string& key) {
        std::lock_guard<std::mutex> lock(cache_mutex_);
        auto it = cache_.find(key);
        if (it != cache_.end() && !it->second.isExpired()) {
            return it->second;
        }
        return std::nullopt;
    }

    void put(const std::string& key, const CachedResult& result) {
        std::lock_guard<std::mutex> lock(cache_mutex_);
        cache_[key] = result;
    }
};

