### Security Best Practices
```cpp
// Security considerations for extensions:

// 1. Input validation
class InputValidator {
public:
    static bool validateString(const std::string& input, size_t max_length = 1024) {
        if (input.empty() || input.length() > max_length) {
            return false;
        }

        // Check for dangerous characters
        static const std::regex dangerous_chars(R"([<>'"&])");
        if (std::regex_search(input, dangerous_chars)) {
            return false;
        }

        return true;
    }

    static bool validatePath(const std::string& path) {
        // Prevent directory traversal
        if (path.find("..") != std::string::npos) {
            return false;
        }

        // Check for valid characters
        static const std::regex valid_path(R"(^[a-zA-Z0-9_\-./]+$)");
        return std::regex_match(path, valid_path);
    }
};

// 2. Secure configuration handling
class SecureConfigManager {
private:
    std::unique_ptr<PsiForceDB::Encryption> encryption_;

public:
    std::string encryptSensitiveData(const std::string& data) {
        if (encryption_) {
            return encryption_->encrypt(data);
        }
        return data; // Fallback - should not happen in production
    }

    std::string decryptSensitiveData(const std::string& encrypted_data) {
        if (encryption_) {
            return encryption_->decrypt(encrypted_data);
        }
        return encrypted_data;
    }
};
