```cpp
// Optimize SELECT queries
class QueryOptimizer {
public:
    // Use specific columns instead of SELECT *
    std::string optimizedSelect() {
        // ❌ Inefficient
        // return "pf://db::select; users";

        // ✅ Efficient - only select needed columns
        return "pf://db::select; users id,name,email --where=\"status='active'\"";
    }

    // Use WHERE clauses to filter early
    std::string filteredQuery() {
        // ❌ Inefficient - filter in application
        // return "pf://db::select; large_table";

        // ✅ Efficient - filter at database level
        return "pf://db::select; large_table --where=\"category='important' AND date > '2025-01-01'\"";
    }

    // Use LIMIT to control result size
    std::string limitedQuery() {
        // ❌ Inefficient - get all results
        // return "pf://db::select; users --where=\"status='active'\"";

        // ✅ Efficient - limit results
        return "pf://db::select; users --where=\"status='active'\" --limit=1000";
    }

    // Use ORDER BY with LIMIT for pagination
    std::string paginatedQuery(int page, int pageSize) {
        int offset = (page - 1) * pageSize;
        return fmt::format(
            "pf://db::select; users --where=\"status='active'\" "
            "--order-by=created_at --limit={} --offset={}",
            pageSize, offset
        );
    }
};
```

### Index Optimization
