// Index management best practices
class IndexOptimizer {
public:
    // Create appropriate indexes
    std::vector<std::string> createOptimalIndexes() {
        return {
            // Primary key index (automatic)
            "pf://db::create_index; users pk_users_id --type=btree --columns=id --unique",

            // Frequently queried columns
            "pf://db::create_index; users idx_users_email --type=hash --columns=email",
            "pf://db::create_index; users idx_users_status_created --type=btree --columns=status,created_at",

            // Composite indexes for complex queries
            "pf://db::create_index; orders idx_orders_user_date --type=btree --columns=user_id,order_date",

            // Full-text search indexes
            "pf://db::create_index; products idx_products_name_fts --type=fulltext --columns=name,description"
        };
    }

    // Monitor index usage
    void analyzeIndexUsage() {
        std::string cmd = "pf://db::analyze_indexes; --verbose --recommend";
        auto result = db.execute(cmd);

        // Process recommendations
        auto recommendations = parseIndexRecommendations(result.data);
        for (const auto& rec : recommendations) {
            if (rec.action == "CREATE") {
                db.execute(rec.command);
            } else if (rec.action == "DROP") {
                // Only drop rarely used indexes
                if (rec.usage_frequency < 0.01) { // Less than 1% usage
                    db.execute(rec.command);
                }
            }
        }
    }
};
```

