        // Get execution plan
        std::string explainCmd = fmt::format(
            "pf://db::explain; {} --format=json --analyze",
            query
        );

        auto result = db.execute(explainCmd);
        auto plan = parseExecutionPlan(result.data);

        // Analyze plan components
        std::cout << "Query Execution Plan Analysis:" << std::endl;
        std::cout << "  Estimated Cost: " << plan.estimatedCost << std::endl;
        std::cout << "  Actual Time: " << plan.actualTime << "ms" << std::endl;
        std::cout << "  Rows Processed: " << plan.rowsProcessed << std::endl;
        std::cout << "  Memory Usage: " << plan.memoryUsage << "MB" << std::endl;

        // Identify bottlenecks
        for (const auto& node : plan.nodes) {
            if (node.cost > plan.estimatedCost * 0.3) { // 30% of total cost
                std::cout << "  ⚠️  High-cost operation: " << node.operation
                         << " (Cost: " << node.cost << ")" << std::endl;
            }
        }
    }

    // Optimize based on analysis
    std::string optimizeQuery(const std::string& originalQuery,
                             const ExecutionPlan& plan) {
        std::string optimizedQuery = originalQuery;

        // Add missing indexes
        for (const auto& recommendation : plan.indexRecommendations) {
            db.execute(recommendation.createCommand);
        }

        // Rewrite query if needed
        if (plan.suggestsRewrite) {
            optimizedQuery = rewriteQueryForPerformance(originalQuery, plan);
        }

        return optimizedQuery;
    }
};
