### Dynamic Access Control
```cpp
// Implement context-aware access control
class ContextAwareAccessControl {
public:
    bool checkAccess(const User& user, const Resource& resource,
                    const RequestContext& context) {
        // Check user permissions
        if (!hasBasicPermission(user, resource)) {
            return false;
        }

        // Check contextual factors
        if (!isAllowedTime(context.timestamp)) {
            auditLog.logAccessDenied(user, resource, "outside_business_hours");
            return false;
        }

        // Check location-based restrictions
        if (!isAllowedLocation(context.ipAddress)) {
            auditLog.logAccessDenied(user, resource, "unauthorized_location");
            return false;
        }

        // Check behavioral patterns
        if (isSuspiciousBehavior(user, context)) {
            auditLog.logAccessDenied(user, resource, "suspicious_behavior");
            triggerSecurityAlert(user, context);
            return false;
        }

        auditLog.logAccessGranted(user, resource);
        return true;
    }
};
```

