class MyEffectPlugin extends GIF3DBasePlugin {
    constructor() {
        super('my_effect');
    }

    initialize(config) {
        super.initialize(config);
        this.effectData = [];
    }

    update(deltaTime) {
        // Update effect data
        this.effectData.push(Math.random());
        if (this.effectData.length > 100) {
            this.effectData.shift();
        }
    }

    render(context) {
        // Render effect
        context.strokeStyle = '#ff6b9d';
        context.lineWidth = 2;

        for (let i = 1; i < this.effectData.length; i++) {
            const x1 = (i - 1) * 8;
            const y1 = 300 - this.effectData[i - 1] * 200;
            const x2 = i * 8;
            const y2 = 300 - this.effectData[i] * 200;

            context.beginPath();
            context.moveTo(x1, y1);
            context.lineTo(x2, y2);
            context.stroke();
        }
    }
}

