// ============================================================================
// FCCP MESSAGE TYPES
// ============================================================================

enum class FCCPMessageType : uint8_t {
    // Control messages
    CONNECT = 0x01,
    DISCONNECT = 0x02,
    PING = 0x03,
    PONG = 0x04,

    // Data messages
    REQUEST = 0x10,
    RESPONSE = 0x11,
    ERROR = 0x12,

    // Database operations
    DB_QUERY = 0x20,
    DB_RESULT = 0x21,
    DB_EXECUTE = 0x22,
    DB_COMMIT = 0x23,
    DB_ROLLBACK = 0x24,

    // Purple Pages operations
    PP_LOG_ERROR = 0x30,
    PP_GET_STATS = 0x31,
    PP_QUERY_ERRORS = 0x32,

    // Notification operations
    NOTIFY_SEND = 0x40,
    NOTIFY_SUBSCRIBE = 0x41,
    NOTIFY_UNSUBSCRIBE = 0x42,

    // Component bridge
    COMPONENT_CALL = 0x50,
    COMPONENT_RESULT = 0x51,

    UNKNOWN = 0xFF
};

// ============================================================================
// FCCP MESSAGE STRUCTURE
// ============================================================================

#pragma pack(push, 1)
struct FCCPMessageHeader {
    uint32_t magic;              // Magic number: 0x46434350 ("FCCP")
    uint8_t version;             // Protocol version (1)
    FCCPMessageType type;        // Message type
    uint16_t flags;              // Message flags
    uint32_t sequence;           // Sequence number
    uint32_t payload_size;       // Payload size in bytes
    uint64_t timestamp;          // Timestamp (microseconds since epoch)

    // Encryption metadata (only used when encryption is enabled)
    uint8_t nonce[12];           // 96-bit nonce for AES-GCM (0 if unencrypted)
    uint8_t tag[16];             // 128-bit authentication tag (0 if unencrypted)

    static constexpr uint32_t MAGIC = 0x46434350;  // "FCCP"
    static constexpr uint8_t VERSION = 1;

    // Flag bits
    static constexpr uint16_t FLAG_ENCRYPTED = 0x0001;
    static constexpr uint16_t FLAG_COMPRESSED = 0x0002;
    static constexpr uint16_t FLAG_ACK_REQUIRED = 0x0004;
};
#pragma pack(pop)

struct FCCPMessage {
    FCCPMessageHeader header;
    std::vector<uint8_t> payload;

    FCCPMessage()
        : header{FCCPMessageHeader::MAGIC, FCCPMessageHeader::VERSION,
                FCCPMessageType::UNKNOWN, 0, 0, 0, 0}
        , payload() {}

    explicit FCCPMessage(FCCPMessageType type)
        : header{FCCPMessageHeader::MAGIC, FCCPMessageHeader::VERSION,
                type, 0, 0, 0, 0}
        , payload() {}

    // Set payload from string
    void set_payload(const std::string& data) {
        payload.assign(data.begin(), data.end());
        header.payload_size = static_cast<uint32_t>(payload.size());
    }

    // Set payload from binary data
    void set_payload(const uint8_t* data, size_t size) {
        payload.assign(data, data + size);
        header.payload_size = static_cast<uint32_t>(size);
    }

    // Get payload as string
    std::string get_payload_string() const {
        return std::string(payload.begin(), payload.end());
    }
};

