#### Discovery 4: Data Isolation Required for Multi-Tenant Junctions
**Date**: 2025-11-18
**Discovered By**: Team 2 (Data Governance)
**Finding**:
```
If Junction Manager is used in multi-tenant environments (multiple products/clients
sharing MedusaServ), junctions MUST enforce data isolation to prevent cross-tenant
data leakage.

Current spec has NO tenant isolation - all junctions are global.

This is CRITICAL for:
- Preventing data leakage between tenants
- GDPR compliance (data subject isolation)
- License enforcement (licensed DLLs only for licensed tenants)
```

**Impact**:
- [X] Requires specification change
- [X] Requires implementation change
- [X] Requires architecture change
- [X] Requires additional testing

**Amendment Required**:
```
Add tenant_id field to JunctionInfo struct.
Add tenant isolation to all junction operations:
- createJunction() must specify tenant_id
- getJunction() must verify caller's tenant_id matches junction's tenant_id
- routeRequest() must verify tenant isolation
- listJunctions() must filter by tenant_id

Add new pp_junction_registry table to track junctions:
CREATE TABLE pp_junction_registry (
    junction_id INT AUTO_INCREMENT PRIMARY KEY,
    junction_uuid VARCHAR(36) UNIQUE NOT NULL,
    junction_name VARCHAR(255) NOT NULL,
    junction_type ENUM('MODULE', 'RESOURCE', 'CACHE', 'CUSTOM'),
    dll_path VARCHAR(500) NOT NULL,
    tenant_id INT NOT NULL,
    created_by INT NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    is_active BOOLEAN DEFAULT TRUE,
    INDEX idx_tenant (tenant_id),
    INDEX idx_active (is_active),
    UNIQUE KEY unique_junction_per_tenant (junction_name, tenant_id)
);
```

**Recommended Changes**:
```cpp
struct JunctionInfo {
    std::string name;
    JunctionType type;
    std::string dll_path;
    std::string version;
    std::vector<std::string> capabilities;
    bool is_active;
    std::chrono::system_clock::time_point load_time;
    int tenant_id;  // NEW: Tenant isolation
    std::string junction_uuid;  // NEW: Unique identifier
};

class JunctionManager : public IJunctionManager {
private:
    // Verify tenant access
    bool verifyTenantAccess(const std::string& junction_name, int tenant_id) {
        auto pstmt = db_connection_->prepareStatement(
            "SELECT tenant_id FROM pp_junction_registry "
            "WHERE junction_name = ? AND is_active = TRUE"
        );
        pstmt->setString(1, junction_name);
        auto res = pstmt->executeQuery();

        if (!res->next()) {
            throw std::runtime_error("Junction not found");
        }

        if (res->getInt("tenant_id") != tenant_id) {
            throw std::runtime_error("Tenant isolation violation");
        }

        return true;
    }

    // Register junction in database
    void registerJunction(const JunctionInfo& info) {
        auto pstmt = db_connection_->prepareStatement(
            "INSERT INTO pp_junction_registry ("
            "  junction_uuid, junction_name, junction_type, dll_path, "
            "  tenant_id, created_by, is_active"
            ") VALUES (UUID(), ?, ?, ?, ?, ?, TRUE)"
        );
        pstmt->setString(1, info.name);
        pstmt->setString(2, junctionTypeToString(info.type));
        pstmt->setString(3, info.dll_path);
        pstmt->setInt(4, info.tenant_id);
        pstmt->setInt(5, /* user_id */);
        pstmt->executeUpdate();
    }

public:
    void* getJunctionInterface(
        const std::string& junction_name,
        const std::string& interface_name,
        int tenant_id  // NEW: Must verify tenant
    ) override {
        // Verify tenant has access to this junction
        if (!verifyTenantAccess(junction_name, tenant_id)) {
            throw std::runtime_error("Tenant isolation violation");
        }

        return getJunctionInterfaceInternal(junction_name, interface_name);
    }

    std::vector<std::string> listJunctions(int tenant_id) const override {
        // Only list junctions for this tenant
        auto pstmt = db_connection_->prepareStatement(
            "SELECT junction_name FROM pp_junction_registry "
            "WHERE tenant_id = ? AND is_active = TRUE "
            "ORDER BY junction_name"
        );
        pstmt->setInt(1, tenant_id);
        auto res = pstmt->executeQuery();

        std::vector<std::string> junctions;
        while (res->next()) {
            junctions.push_back(res->getString("junction_name"));
        }
        return junctions;
    }
};
