namespace psiforcedb::formats {

// Dome File Format v0.1 - Basic AES encryption
// v1.0 will add PQC (Kyber/Dilithium)

constexpr uint32_t DOME_MAGIC = 0x00534950;  // "PSI\0" little-endian
constexpr uint32_t DOME_VERSION = 0x00000001; // v0.1
constexpr size_t DOME_HEADER_SIZE = 256;       // Simplified for v0.1
constexpr size_t DOME_CHUNK_SIZE = 4096;       // 4KB chunks

enum class DomeError : uint32_t {
    SUCCESS = 0,
    INVALID_MAGIC = 1,
    UNSUPPORTED_VERSION = 2,
    PASSWORD_INCORRECT = 3,
    IO_ERROR = 4,
    ALREADY_OPEN = 5,
    NOT_OPEN = 6,
};

struct DomeHeader {
    uint32_t magic;           // "PSI\0"
    uint32_t version;         // 0x00000001
    uint8_t uuid[16];         // Random UUID
    uint8_t salt[32];         // Argon2 salt
    uint8_t iv[16];           // AES IV
    uint64_t data_size;       // Unencrypted data size
    uint64_t chunk_count;     // Number of encrypted chunks
    uint8_t checksum[32];     // SHA-256 of header (except this field)
    uint8_t reserved[128];    // Reserved for v1.0 PQC fields
} __attribute__((packed));

class DomeFile {
public:
    DomeFile();
    ~DomeFile();

    // Non-copyable
    DomeFile(const DomeFile&) = delete;
    DomeFile& operator=(const DomeFile&) = delete;

    // Movable
    DomeFile(DomeFile&&) noexcept;
    DomeFile& operator=(DomeFile&&) noexcept;

    // Create new dome
    static std::optional<DomeError> create(
        const std::string& path,
        const std::string& password
    );

    // Open existing dome
    DomeError open(const std::string& path, const std::string& password);
    void close();

    // Check if open
    bool isOpen() const { return is_open_; }

    // Write data (append-only in v0.1)
    DomeError write(const std::vector<uint8_t>& data);
    DomeError write(const std::string& data);

    // Read all data
    std::variant<std::vector<uint8_t>, DomeError> readAll();

    // Read range (if supported)
    std::variant<std::vector<uint8_t>, DomeError> read(uint64_t offset, size_t length);

    // Get UUID
    std::string getUUID() const;

    // Get data size
    uint64_t getDataSize() const { return header_.data_size; }

private:
    bool is_open_ = false;
    std::string path_;
    int fd_ = -1;  // File descriptor
    DomeHeader header_;
    std::vector<uint8_t> key_;  // AES-256 key (32 bytes)

    // Internal methods
    DomeError deriveKey(const std::string& password, const uint8_t* salt);
    std::vector<uint8_t> encryptChunk(const std::vector<uint8_t>& plaintext, 
                                       uint64_t chunk_index);
    std::variant<std::vector<uint8_t>, DomeError> decryptChunk(uint64_t chunk_index);
    DomeError updateHeader();
};

} // namespace psiforcedb::formats
```

**Implementation** (`dome_format.cpp` - key functions):
```cpp
#include "psiforcedb/formats/dome_format.hpp"
#include <openssl/evp.h>
#include <openssl/sha.h>
#include <openssl/rand.h>
#include <openssl/kdf.h>
#include <fcntl.h>
#include <unistd.h>
#include <cstring>

namespace psiforcedb::formats {

// Argon2 parameters (adjust for security/performance)
constexpr uint32_t ARGON2_ITERATIONS = 3;
constexpr uint32_t ARGON2_MEMORY = 65536;  // 64 MB
constexpr uint32_t ARGON2_PARALLELISM = 4;

std::optional<DomeError> DomeFile::create(const std::string& path,
                                          const std::string& password) {
    DomeFile dome;

    // Generate random UUID
    uint8_t uuid[16];
    if (RAND_bytes(uuid, 16) != 1) {
        return DomeError::IO_ERROR;
    }

    // Generate random salt
    uint8_t salt[32];
    if (RAND_bytes(salt, 32) != 1) {
        return DomeError::IO_ERROR;
    }

    // Generate random IV
    uint8_t iv[16];
    if (RAND_bytes(iv, 16) != 1) {
        return DomeError::IO_ERROR;
    }

    // Derive key
    std::vector<uint8_t> key(32);
    // TODO: Use Argon2 - for now use PBKDF2 for v0.1
    if (!PKCS5_PBKDF2_HMAC(password.c_str(), password.length(),
                           salt, 32,
                           100000,  // iterations
                           EVP_sha256(),
                           32, key.data())) {
        return DomeError::IO_ERROR;
    }

    // Build header
    dome.header_.magic = DOME_MAGIC;
    dome.header_.version = DOME_VERSION;
    memcpy(dome.header_.uuid, uuid, 16);
    memcpy(dome.header_.salt, salt, 32);
    memcpy(dome.header_.iv, iv, 16);
    dome.header_.data_size = 0;
    dome.header_.chunk_count = 0;
    memset(dome.header_.checksum, 0, 32);
    memset(dome.header_.reserved, 0, 128);

    // Calculate header checksum
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, &dome.header_, offsetof(DomeHeader, checksum));
    SHA256_Final(dome.header_.checksum, &ctx);

    // Create file
    int fd = open(path.c_str(), O_CREAT | O_EXCL | O_RDWR, 0600);
    if (fd < 0) {
        return DomeError::IO_ERROR;
    }

    // Write header
    if (write(fd, &dome.header_, sizeof(DomeHeader)) != sizeof(DomeHeader)) {
        close(fd);
        unlink(path.c_str());
        return DomeError::IO_ERROR;
    }

    close(fd);
    return std::nullopt;  // Success
}

DomeError DomeFile::open(const std::string& path, const std::string& password) {
    if (is_open_) {
        return DomeError::ALREADY_OPEN;
    }

    fd_ = open(path.c_str(), O_RDWR);
    if (fd_ < 0) {
        return DomeError::IO_ERROR;
    }

    // Read header
    if (read(fd_, &header_, sizeof(DomeHeader)) != sizeof(DomeHeader)) {
        close(fd_);
        fd_ = -1;
        return DomeError::IO_ERROR;
    }

    // Validate magic
    if (header_.magic != DOME_MAGIC) {
        close(fd_);
        fd_ = -1;
        return DomeError::INVALID_MAGIC;
    }

    // Validate version
    if (header_.version != DOME_VERSION) {
        close(fd_);
        fd_ = -1;
        return DomeError::UNSUPPORTED_VERSION;
    }

    // Verify checksum
    uint8_t computed_checksum[32];
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, &header_, offsetof(DomeHeader, checksum));
    SHA256_Final(computed_checksum, &ctx);

    if (memcmp(computed_checksum, header_.checksum, 32) != 0) {
        close(fd_);
        fd_ = -1;
        return DomeError::IO_ERROR;  // Corrupted
    }

    // Derive key
    key_.resize(32);
    if (!PKCS5_PBKDF2_HMAC(password.c_str(), password.length(),
                           header_.salt, 32,
                           100000,
                           EVP_sha256(),
                           32, key_.data())) {
        close(fd_);
        fd_ = -1;
        return DomeError::IO_ERROR;
    }

    // Test decryption on first chunk (if data exists)
    if (header_.chunk_count > 0) {
        auto result = decryptChunk(0);
        if (std::holds_alternative<DomeError>(result)) {
            close(fd_);
            fd_ = -1;
            key_.clear();
            return DomeError::PASSWORD_INCORRECT;
        }
    }

    path_ = path;
    is_open_ = true;
    return DomeError::SUCCESS;
}

DomeError DomeFile::write(const std::vector<uint8_t>& data) {
    if (!is_open_) {
        return DomeError::NOT_OPEN;
    }

    // Split into chunks
    size_t offset = 0;
    uint64_t chunk_index = header_.chunk_count;

    while (offset < data.size()) {
        size_t chunk_size = std::min(DOME_CHUNK_SIZE, data.size() - offset);
        std::vector<uint8_t> chunk(data.begin() + offset, 
                                   data.begin() + offset + chunk_size);

        // Encrypt chunk
        auto encrypted = encryptChunk(chunk, chunk_index);

        // Write to file (after header, at correct offset)
        size_t file_offset = sizeof(DomeHeader) + 
                            (chunk_index * (DOME_CHUNK_SIZE + 16)); // +16 for tag

        if (lseek(fd_, file_offset, SEEK_SET) < 0) {
            return DomeError::IO_ERROR;
        }

        if (::write(fd_, encrypted.data(), encrypted.size()) != 
            static_cast<ssize_t>(encrypted.size())) {
            return DomeError::IO_ERROR;
        }

        offset += chunk_size;
        chunk_index++;
    }

    // Update header
    header_.data_size += data.size();
    header_.chunk_count = chunk_index;

    // Recalculate checksum
    SHA256_CTX ctx;
    SHA256_Init(&ctx);
    SHA256_Update(&ctx, &header_, offsetof(DomeHeader, checksum));
    SHA256_Final(header_.checksum, &ctx);

    // Write updated header
    if (lseek(fd_, 0, SEEK_SET) < 0) {
        return DomeError::IO_ERROR;
    }

    if (::write(fd_, &header_, sizeof(DomeHeader)) != sizeof(DomeHeader)) {
        return DomeError::IO_ERROR;
    }

    fsync(fd_);
    return DomeError::SUCCESS;
}

std::vector<uint8_t> DomeFile::encryptChunk(const std::vector<uint8_t>& plaintext,
                                            uint64_t chunk_index) {
    // Derive per-chunk IV: IV || chunk_index (as 64-bit counter)
    uint8_t iv[16];
    memcpy(iv, header_.iv, 16);
    // XOR chunk_index into last 8 bytes of IV
    for (int i = 0; i < 8; i++) {
        iv[8 + i] ^= (chunk_index >> (i * 8)) & 0xFF;
    }

    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx, EVP_aes_256_gcm(), nullptr, key_.data(), iv);

    std::vector<uint8_t> ciphertext(plaintext.size() + 16); // +16 for tag
    int len;

    EVP_EncryptUpdate(ctx, ciphertext.data(), &len, 
                      plaintext.data(), plaintext.size());
    int ciphertext_len = len;

    EVP_EncryptFinal_ex(ctx, ciphertext.data() + len, &len);
    ciphertext_len += len;

    // Get tag
    uint8_t tag[16];
    EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag);

    EVP_CIPHER_CTX_free(ctx);

    // Append tag
    memcpy(ciphertext.data() + ciphertext_len, tag, 16);
    ciphertext.resize(ciphertext_len + 16);

    return ciphertext;
}

} // namespace psiforcedb::formats
