```cpp
bool KeyRotationEngine::rotateKeys(const RotationConfig& config) {
    // Create rotation state file for resume capability
    auto state = createRotationState(config.dome_path);

    // Step 1: Open dome with old keys
    DomeFile old_dome;
    if (!old_dome.open(config.dome_path, config.old_password)) {
        return false;
    }

    // Step 2: Create new dome file with rotated keys
    std::string rotated_path = config.dome_path + ".rotating";

    // Step 3: Copy and re-encrypt all data
    auto chunk_count = old_dome.getChunkCount();
    for (uint64_t i = 0; i < chunk_count; i++) {
        // Decrypt with old key
        auto plaintext = old_dome.decryptChunk(i);
        if (!plaintext) {
            return false;
        }

        // Encrypt with new key
        auto new_ciphertext = encryptChunk(*plaintext, new_key, new_iv);

        // Write to rotated dome
        writeRotatedChunk(rotated_path, i, new_ciphertext);

        // Update progress
        if (config.progress_callback) {
            config.progress_callback(static_cast<double>(i) / chunk_count);
        }
    }

    // Step 4: Atomic rename
    if (!atomicRename(rotated_path, config.dome_path)) {
        return false;
    }

    // Step 5: Verify
    if (config.verify_after) {
        return verifyAfterRotation(config.dome_path);
    }

    return true;
}
