void PFQLCompiler::compileScanTable(const PFQLScanOp& op) {
    // Function prologue
    emitter_.emitFunctionPrologue();

    // Load table pointer into RDI
    emitter_.emitMovImm(Register::RDI, reinterpret_cast<uint64_t>(op.table));

    // Load callback into RSI
    emitter_.emitMovImm(Register::RSI, reinterpret_cast<uint64_t>(rowCallback));

    // Call scan function
    emitter_.emitCall(reinterpret_cast<void*>(tableScanImpl));

    // Function epilogue
    emitter_.emitFunctionEpilogue();
    emitter_.emitRet();
}

void PFQLCompiler::compileFilter(const PFQLFilterOp& op) {
    // Load column value
    emitter_.emitLoad(Register::RAX, Register::RDI, op.column_offset);

    // Load comparison value
    emitter_.emitMovImm(Register::RBX, op.value);

    // Compare
    emitter_.emitCmp(Register::RAX, Register::RBX);

    // Jump if condition not met
    switch (op.condition) {
        case FilterCondition::EQ:
            emitter_.emitJne(skip_label);
            break;
        case FilterCondition::LT:
            emitter_.emitJge(skip_label);
            break;
        // ... etc
    }
}
