template<size_t Size>
class SecureLockedBuffer {
public:
    SecureLockedBuffer() {
        // Allocate with guard pages
        memory_ = allocateLockedMemory(Size);

        // Lock into physical RAM
        lockMemory(memory_, Size);

        // Prevent core dumps
        preventCoreDumps();
    }

    ~SecureLockedBuffer() {
        // Secure clear
        secureClear(memory_, Size);

        // Unlock
        unlockMemory(memory_, Size);

        // Free
        freeLockedMemory(memory_, Size);
    }

    uint8_t* data() { return memory_; }
    size_t size() const { return Size; }

private:
    uint8_t* memory_;
};

// Platform-specific implementation
#ifdef _WIN32
    void* allocateLockedMemory(size_t size) {
        // VirtualAlloc with MEM_PHYSICAL
        return VirtualAlloc(nullptr, size, 
                           MEM_COMMIT | MEM_RESERVE | MEM_PHYSICAL,
                           PAGE_READWRITE);
    }

    void lockMemory(void* addr, size_t size) {
        VirtualLock(addr, size);
    }
#else
    void* allocateLockedMemory(size_t size) {
        void* ptr = mmap(nullptr, size, PROT_READ | PROT_WRITE,
                        MAP_PRIVATE | MAP_ANONYMOUS | MAP_LOCKED, -1, 0);
        return ptr;
    }

    void lockMemory(void* addr, size_t size) {
        mlock(addr, size);
    }
#endif
