## USAGE EXAMPLES

### Client Sending PFQL Query

```cpp
#include "psiforcedb/protocol/encrypted_transport.hpp"
#include "psiforcedb/crypto/pqc_handshake.hpp"

// After PQC handshake establishes session keys
psiforcedb::crypto::SessionKeys session_keys = handshake.deriveSessionKeys();

// Create transport
psiforcedb::protocol::TransportConfig config;
config.socket_fd = socket_fd;
config.session_keys = &session_keys;
config.is_client = true;

psiforcedb::protocol::EncryptedTransport transport(config);

// Send PFQL query
std::string pfql = "SELECT * FROM users WHERE id = 1";
std::vector<uint8_t> payload(pfql.begin(), pfql.end());
bool sent = transport.sendPacket(
    payload,
    psiforcedb::protocol::MessageType::PFQL_QUERY,
    12345  // request_id
);
```

### Server Receiving and Processing

```cpp
// Server-side transport setup
psiforcedb::protocol::TransportConfig config;
config.socket_fd = client_socket;
config.session_keys = &session_keys;
config.is_client = false;  // Server mode

psiforcedb::protocol::EncryptedTransport transport(config);

// Receive and process
auto decoded = transport.receiveDecodedPacket();
if (decoded) {
    switch (decoded->message_type) {
        case psiforcedb::protocol::MessageType::PFQL_QUERY:
            handlePFQLQuery(decoded->payload, decoded->request_id);
            break;
        case psiforcedb::protocol::MessageType::BASH_COMMAND:
            handleBashCommand(decoded->payload, decoded->request_id);
            break;
        // ... etc
    }
}
```

