// === ADD THIS FUNCTION ===
std::shared_ptr<ASTNode> SQLParser::parseCreateDatabase() {
    auto node = std::make_shared<ASTNode>(ASTNodeType::CREATE_DATABASE);

    // Expect database name
    if (!check(TokenType::IDENTIFIER)) {
        error("Expected database name after CREATE DATABASE");
        return nullptr;
    }

    Token db_name = consume(TokenType::IDENTIFIER, "Expected database name");
    node->setAttribute("database_name", db_name.lexeme);

    // Optional: WITH ENCRYPTION, WITH OWNER, etc.
    while (match(TokenType::WITH)) {
        if (match(TokenType::OWNER)) {
            Token owner = consume(TokenType::IDENTIFIER, "Expected owner name");
            node->setAttribute("owner", owner.lexeme);
        } else if (match(TokenType::ENCODING)) {
            Token encoding = consume(TokenType::STRING, "Expected encoding");
            node->setAttribute("encoding", encoding.lexeme);
        } else {
            break;
        }
    }

    return node;
}
