#include <iostream>
#include <string>
#include <vector>
#include <cstring>
#include "psiforcedb/formats/dome_format.hpp"

using namespace psiforcedb::formats;

void printUsage(const char* program) {
    std::cout << "PsiForceDB CLI v0.1\n\n";
    std::cout << "Usage: " << program << " <command> [options]\n\n";
    std::cout << "Commands:\n";
    std::cout << "  create-dome <path>    Create a new encrypted dome\n";
    std::cout << "  open-dome <path>      Open and decrypt a dome\n";
    std::cout << "  write-dome <path>     Write data to dome (stdin)\n";
    std::cout << "  read-dome <path>      Read data from dome (stdout)\n";
    std::cout << "  help                  Show this help\n";
}

int cmdCreateDome(int argc, char* argv[]) {
    if (argc < 3) {
        std::cerr << "Usage: create-dome <path>\n";
        return 1;
    }

    std::string path = argv[2];

    std::cout << "Enter password: ";
    std::string password;
    std::getline(std::cin, password);

    auto error = DomeFile::create(path, password);
    if (error) {
        std::cerr << "Failed to create dome: " << static_cast<uint32_t>(*error) << "\n";
        return 1;
    }

    std::cout << "Dome created: " << path << "\n";
    return 0;
}

int cmdWriteDome(int argc, char* argv[]) {
    if (argc < 3) {
        std::cerr << "Usage: write-dome <path>\n";
        return 1;
    }

    std::string path = argv[2];

    std::cout << "Enter password: ";
    std::string password;
    std::getline(std::cin, password);

    DomeFile dome;
    auto error = dome.open(path, password);
    if (error != DomeError::SUCCESS) {
        std::cerr << "Failed to open dome: " << static_cast<uint32_t>(error) << "\n";
        return 1;
    }

    // Read all stdin
    std::vector<uint8_t> data;
    char buffer[4096];
    while (std::cin.read(buffer, sizeof(buffer)) || std::cin.gcount() > 0) {
        data.insert(data.end(), buffer, buffer + std::cin.gcount());
    }

    error = dome.write(data);
    if (error != DomeError::SUCCESS) {
        std::cerr << "Failed to write: " << static_cast<uint32_t>(error) << "\n";
        return 1;
    }

    std::cout << "Wrote " << data.size() << " bytes\n";
    return 0;
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        printUsage(argv[0]);
        return 1;
    }

    std::string command = argv[1];

    if (command == "create-dome") {
        return cmdCreateDome(argc, argv);
    } else if (command == "write-dome") {
        return cmdWriteDome(argc, argv);
    } else if (command == "help" || command == "--help" || command == "-h") {
        printUsage(argv[0]);
        return 0;
    } else {
        std::cerr << "Unknown command: " << command << "\n";
        printUsage(argv[0]);
        return 1;
    }
}
