    auto enc_result = KyberKEM::encapsulate(kyber_keys.public_key);

    // Derive AES key from shared secret + password hash
    auto aes_key = hkdf_sha256(
        enc_result.shared_secret,
        password_hash,
        "PsiForceDB-Backup-v1"
    );

    return {aes_key, hmac_key, enc_result.ciphertext};
