class ReplayProtection {
public:
    static constexpr size_t WINDOW_SIZE = 1024;

    bool isReplay(uint64_t sequence_number) {
        if (sequence_number < window_start_) {
            // Too old - definitely replay
            return true;
        }

        if (sequence_number >= window_start_ + WINDOW_SIZE) {
            // Advance window
            window_start_ = sequence_number - WINDOW_SIZE + 1;
            received_sequences_.reset();
        }

        size_t offset = sequence_number - window_start_;
        if (received_sequences_.test(offset)) {
            // Already received - replay!
            return true;
        }

        received_sequences_.set(offset);
        return false;
    }

private:
    uint64_t window_start_ = 0;
    std::bitset<WINDOW_SIZE> received_sequences_;
};
