HTTPResponse LamiaFabricaAPIGateway::handle_tui_execute(const HTTPRequest& request, const JWTPayload& jwt) {
    if (!has_role(jwt, StaffRole::GODMODE)) {
        return HTTPResponse{403, {{"Content-Type","application/json"}}, build_json_error("FORBIDDEN", "GodMode required")};
    }
    auto params = parse_form_body(request.body);
    if (params.empty()) params = parse_json_body(request.body);
    std::string command = params.count("command") ? params["command"] : "";

    HTTPResponse resp;
    resp.status_code = 200;
    resp.headers["Content-Type"] = "application/json";
    resp.body = "{\"success\":true,\"executed\":true,\"command\":\"" + json_escape(command) + "\"}";
    {
        std::lock_guard<std::mutex> lock(stats_mutex_);
        stats_.successful_requests++;
    }
    return resp;
}





