    std::vector<PsiForceDB::Network::MiniHubInfo> hubs;
    if (mini_hub_connector_) {
        hubs = mini_hub_connector_->get_connected_hubs();
    }

    std::ostringstream json;
    json << "{\"success\":true,\"hub_count\":" << hubs.size() << ",\"hubs":" << '[';
    for (size_t i = 0; i < hubs.size(); ++i) {
        if (i > 0) json << ",";
        const auto& h = hubs[i];
        json << "{"
             << "\"hub_id\":\"" << json_escape(h.hub_id) << "\","
             << "\"name\":\"" << json_escape(h.name) << "\","
             << "\"ip_address\":\"" << json_escape(h.ip_address) << "\","
             << "\"ports\":{";
        bool first_port = true;
        for (const auto& [pname, pval] : h.ports) {
            if (!first_port) json << ",";
            json << "\"" << json_escape(pname) << "\":" << pval;
            first_port = false;
        }
        json << "},"
             << "\"bond_strength\":" << h.bond_strength << ","
             << "\"trust_level\":" << h.trust_level << ","
             << "\"public_key_fingerprint\":\"" << json_escape(h.public_key_fingerprint) << "\""
             << "}";
    }
    json << "]}";

    HTTPResponse resp;
    resp.status_code = 200;
    resp.headers["Content-Type"] = "application/json";
    resp.body = json.str();
    {
        std::lock_guard<std::mutex> lock(stats_mutex_);
        stats_.successful_requests++;
    }
    return resp;
}

HTTPResponse LamiaFabricaAPIGateway::handle_infrastructure_hub_bond(const HTTPRequest& request, const JWTPayload& jwt) {
    if (!authorize_action(jwt, Permission::WRITE)) {
        return HTTPResponse{403, {{"Content-Type","application/json"}}, build_json_error("FORBIDDEN", "Write permission required")};
    }

    std::string prefix = "/api/v1/infrastructure/hubs/";
    std::string rest = request.path.substr(prefix.size());
    size_t slash = rest.find('/');
    if (slash == std::string::npos) {
        return HTTPResponse{400, {{"Content-Type","application/json"}}, build_json_error("BAD_REQUEST", "Invalid hub path")};
    }
    std::string hub_id = rest.substr(0, slash);

    if (!mini_hub_connector_) {
        return HTTPResponse{503, {{"Content-Type","application/json"}}, build_json_error("SERVICE_UNAVAILABLE", "Mini-Hub Connector not initialized")};
    }

    auto hubs = mini_hub_connector_->get_connected_hubs();
    auto it = std::find_if(hubs.begin(), hubs.end(), [&hub_id](const auto& h) { return h.hub_id == hub_id; });
    if (it == hubs.end()) {
        return HTTPResponse{404, {{"Content-Type","application/json"}}, build_json_error("NOT_FOUND", "Hub not found")};
    }

    using namespace psiforcedb::nemadic::v2;
    std::hash<std::string> hasher;
    ID nid = static_cast<ID>(hasher(hub_id));
    GlobalBondRegistry::instance().add_bond(nid, Bond{nid + 2, 0.95f, BondType::SEMANTIC, 72.0f, false});

    HTTPResponse resp;
    resp.status_code = 200;
    resp.headers["Content-Type"] = "application/json";
    resp.body = "{\"success\":true,\"message\":\"Bond created\",\"hub_id\":\"" + json_escape(hub_id) + "\"}";
    {
        std::lock_guard<std::mutex> lock(stats_mutex_);
        stats_.successful_requests++;
    }
    return resp;
}

